import{_ as o,o as e,c as l,a as r}from"./app.DkoUFz-u.js";const u=JSON.parse('{"title":"redis 高频面试题","description":"","frontmatter":{},"headers":[],"relativePath":"data/database/nosql/keyvalue/redis/interview.md","filePath":"data/database/nosql/keyvalue/redis/interview.md"}'),i={name:"data/database/nosql/keyvalue/redis/interview.md"};function d(s,t,n,a,g,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="redis-高频面试题" tabindex="-1">redis 高频面试题 <a class="header-anchor" href="#redis-高频面试题" aria-label="Permalink to &quot;redis 高频面试题&quot;">​</a></h1><h3 id="_1-五种基本数据类型及典型场景" tabindex="-1">1. 五种基本数据类型及典型场景 <a class="header-anchor" href="#_1-五种基本数据类型及典型场景" aria-label="Permalink to &quot;1. 五种基本数据类型及典型场景&quot;">​</a></h3><ul><li><p><strong>String</strong><br> 缓存对象（JSON 序列化）、常规计数（点赞数、阅读量）、分布式锁（<code>SETNX</code>）、分布式 Session 共享。</p></li><li><p><strong>Hash</strong><br> 存储对象属性（用户信息、商品详情），便于单独更新某个字段，避免频繁的序列化开销。</p></li><li><p><strong>List</strong><br> 消息队列（<code>LPUSH</code> / <code>RPOP</code>）、最新动态/消息列表（朋友圈时间轴）、阻塞队列（<code>BRPOP</code>）。</p></li><li><p><strong>Set</strong><br> 标签系统（用户兴趣标签）、共同好友/交集计算（<code>SINTER</code>）、抽奖去重、唯一性约束。</p></li><li><p><strong>Sorted Set (ZSet)</strong><br> 各类排行榜（积分排名、热度榜）、延时队列（score 为到期时间戳）、带权重的集合。</p></li></ul><hr><h3 id="_2-redis-过期键删除策略" tabindex="-1">2. Redis 过期键删除策略 <a class="header-anchor" href="#_2-redis-过期键删除策略" aria-label="Permalink to &quot;2. Redis 过期键删除策略&quot;">​</a></h3><p>Redis 采用 <strong>惰性删除 + 定期删除</strong> 的组合策略。</p><ul><li><strong>惰性删除</strong>：访问 key 时检查是否过期，过期则删除。优点是 CPU 友好，缺点是内存不友好，长期未访问的过期键会残留。</li><li><strong>定期删除</strong>：每秒执行 10 次左右，随机抽检一批带过期时间的 key 并清除。若抽检中过期比例超 25%，则循环继续，在 CPU 与内存间取得平衡。</li><li><strong>内存淘汰策略</strong>：作为兜底，当内存触及 <code>maxmemory</code> 上限时，即使 key 未过期，也会按配置策略（如 LRU、LFU）强制淘汰。</li></ul><p><strong>最佳实践：</strong></p><ul><li>设置过期时间时加一个随机偏移量，防止集体失效引发缓存雪崩。</li><li>删除大 key 时用 <code>UNLINK</code> 异步删除，防止阻塞主线程。</li><li>监控过期 key 数量，关注定期删除的执行效率。</li></ul><hr><h3 id="_3-持久化机制-rdb-与-aof" tabindex="-1">3. 持久化机制：RDB 与 AOF <a class="header-anchor" href="#_3-持久化机制-rdb-与-aof" aria-label="Permalink to &quot;3. 持久化机制：RDB 与 AOF&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>RDB (快照)</th><th>AOF (追加文件)</th></tr></thead><tbody><tr><td><strong>原理</strong></td><td>将某一时刻的内存数据快照保存为二进制文件</td><td>以独立日志形式记录每次写操作，重启时重放</td></tr><tr><td><strong>文件大小</strong></td><td>紧凑，压缩率高</td><td>通常更大，可通过重写优化</td></tr><tr><td><strong>数据恢复</strong></td><td>极快，适合灾难恢复</td><td>取决于日志规模，相对较慢</td></tr><tr><td><strong>数据安全性</strong></td><td>可能丢失最近一次快照后的所有修改</td><td><code>everysec</code> 策略下最多丢失1秒数据</td></tr><tr><td><strong>备份策略</strong></td><td>适合周期性冷备</td><td>适合实时持久化</td></tr><tr><td><strong>主进程影响</strong></td><td><code>bgsave</code> 会 fork 子进程，有瞬时的 CPU/内存开销</td><td>AOF 写入有 I/O 开销，重写时 fork 子进程</td></tr></tbody></table><ul><li><strong>混合持久化 (Redis 4.0+)</strong>：AOF 重写时，以 RDB 格式记录当前数据，再追加增量 AOF 命令。文件结构为 RDB 头部 + AOF 尾部，兼具恢复速度快和数据完整度高的优点。</li><li><strong>生产环境建议</strong>：两者同时开启，并启用混合持久化。RDB 做冷备，AOF 保障数据安全。</li></ul><hr><h3 id="_4-分布式锁" tabindex="-1">4. 分布式锁 <a class="header-anchor" href="#_4-分布式锁" aria-label="Permalink to &quot;4. 分布式锁&quot;">​</a></h3><ul><li><strong>核心实现</strong>：<code>SET key value NX PX 30000</code> 原子性地完成加锁与超时设置。解锁时必须用 Lua 脚本校验 value（客户端唯一标识），原子地判断并删除，防止误解锁。</li><li><strong>Redisson 看门狗机制</strong>：若业务未显式设置过期时间，Redisson 会启动后台任务，默认每 10 秒自动续期 30 秒，直到业务主动释放。解决锁自动过期、任务未执行完的问题。</li><li><strong>红锁 (RedLock)</strong>：适用于多个独立 Redis 主节点的场景，尝试过半节点加锁成功才算获得锁，旨在提升主从切换时的安全性。但业界存在争议，强一致性场景可考虑 Zookeeper 或 etcd。</li><li><strong>关键点</strong>：必须加过期时间、必须原子释放，生产中推荐直接使用 Redisson 等成熟客户端。</li></ul><hr><h3 id="_5-大-key-问题" tabindex="-1">5. 大 Key 问题 <a class="header-anchor" href="#_5-大-key-问题" aria-label="Permalink to &quot;5. 大 Key 问题&quot;">​</a></h3><ul><li><strong>定义</strong>：String 大于 10KB，或集合元素数过多（如几万个以上），都可视为大 Key。</li><li><strong>危害</strong>：读写操作极慢，易引发 Redis 主线程阻塞；删除大 Key 可能导致服务卡顿；在集群中会造成内存与请求不均（数据倾斜）。</li><li><strong>发现</strong>：<code>redis-cli --bigkeys</code>、<code>MEMORY USAGE</code> 命令，或离线分析 RDB 文件。</li><li><strong>处理方案</strong>： <ul><li>设计时拆分为多个小 Key。</li><li>读取时只取必要字段或分批获取。</li><li>删除时使用 <code>UNLINK</code> 异步操作，或结合 <code>SCAN</code> 分批删除。</li><li>集群场景下对 Value 过大需进行压缩。</li></ul></li></ul><hr><h3 id="_6-特殊数据类型-hyperloglog-与布隆过滤器" tabindex="-1">6. 特殊数据类型：HyperLogLog 与布隆过滤器 <a class="header-anchor" href="#_6-特殊数据类型-hyperloglog-与布隆过滤器" aria-label="Permalink to &quot;6. 特殊数据类型：HyperLogLog 与布隆过滤器&quot;">​</a></h3><ul><li><p><strong>HyperLogLog (基数统计)</strong></p><ul><li><strong>用途</strong>：海量数据的 UV 统计等不精确去重场景。</li><li><strong>原理</strong>：基于概率算法，每个 Key 仅占 12KB，可统计 2^64 个元素，标准误差约 0.81%。</li><li><strong>命令</strong>：<code>PFADD</code> 添加，<code>PFCOUNT</code> 统计，<code>PFMERGE</code> 合并。</li><li><strong>特点</strong>：不保留原始数据，无法获取具体成员元素。</li></ul></li><li><p><strong>布隆过滤器 (Bloom Filter)</strong></p><ul><li><strong>用途</strong>：解决缓存穿透、黑名单校验、爬虫 URL 去重等。</li><li><strong>原理</strong>：由位数组和多个哈希函数构成。存在判定结果：“一定不存在” 或 “可能存在”，有可接受的误判率。</li><li><strong>Redis 模块</strong>：RedisBloom 提供 <code>BF.ADD</code>、<code>BF.EXISTS</code> 等命令。</li><li><strong>经典场景</strong>：将所有数据库主键放入布隆过滤器，查询命中“不存在”时直接返回，避免无效请求冲击数据库。</li></ul></li></ul><hr><h3 id="_7-集群体系-主从、哨兵、cluster" tabindex="-1">7. 集群体系：主从、哨兵、Cluster <a class="header-anchor" href="#_7-集群体系-主从、哨兵、cluster" aria-label="Permalink to &quot;7. 集群体系：主从、哨兵、Cluster&quot;">​</a></h3><ul><li><p><strong>主从复制</strong></p><ul><li><strong>作用</strong>：数据冗余备份、读写分离、故障恢复的基础。</li><li><strong>原理</strong>：从节点 <code>PSYNC</code> 发起同步，支持全量（RDB）和部分复制（偏移量）。主节点持续异步推送写命令。</li><li><strong>痛点</strong>：复制延迟导致的数据一致性问题；主节点故障需人工或哨兵介入切换。</li></ul></li><li><p><strong>哨兵 (Sentinel)</strong></p><ul><li><strong>功能</strong>：监控、通知、自动故障转移、配置提供者。</li><li><strong>流程</strong>：多哨兵监控节点，经主观下线（SDOWN）与客观下线（ODOWN）判定后，选举 Leader 哨兵执行故障转移：选出新主 → 重定向从节点 → 通知客户端。</li><li><strong>部署</strong>：至少 3 个哨兵实例保证自身高可用。</li></ul></li><li><p><strong>Cluster 集群</strong></p><ul><li><strong>原理</strong>：数据分片，划分 <strong>16384 个哈希槽</strong>，<code>CRC16(key) % 16384</code> 定位槽，每个主节点负责部分槽。</li><li><strong>特点</strong>：去中心化，节点间 Gossip 通信；客户端缓存槽映射，遇 <code>MOVED</code> 重定向自动更新；自带主从故障转移。</li><li><strong>限制</strong>：跨槽的事务或多 Key 操作不被支持；Lua 脚本中操作的 Key 必须在同一槽（可通过 <code>hash tag</code> 解决）。</li><li><strong>选型对比</strong>：哨兵模式侧重高可用与数据冗余，适合中小规模；Cluster 侧重水平扩展与数据分片，适合海量数据场景。</li></ul></li></ul><hr><h3 id="_8-缓存穿透、击穿、雪崩" tabindex="-1">8. 缓存穿透、击穿、雪崩 <a class="header-anchor" href="#_8-缓存穿透、击穿、雪崩" aria-label="Permalink to &quot;8. 缓存穿透、击穿、雪崩&quot;">​</a></h3><ul><li><strong>缓存穿透</strong>：查询一个数据库和缓存都不存在的数据。 <ul><li><strong>解决</strong>：布隆过滤器快速拦截；或缓存空值并设短过期时间。</li></ul></li><li><strong>缓存击穿</strong>：单个热点 Key 过期的瞬间，大量并发请求直达数据库。 <ul><li><strong>解决</strong>：分布式互斥锁，仅允许一个请求查询并回写；或使用逻辑过期，异步刷新缓存。</li></ul></li><li><strong>缓存雪崩</strong>：大量 Key 在同一时间过期，或 Redis 整体宕机，请求涌向数据库。 <ul><li><strong>解决</strong>：过期时间加随机偏移；构建多级缓存；核心服务限流降级；Redis 采用主从+哨兵/集群保障高可用。</li></ul></li></ul><hr><h3 id="_9-redis-单线程与高性能" tabindex="-1">9. Redis 单线程与高性能 <a class="header-anchor" href="#_9-redis-单线程与高性能" aria-label="Permalink to &quot;9. Redis 单线程与高性能&quot;">​</a></h3><ul><li><strong>快的原因</strong>： <ul><li><strong>内存操作</strong>：绝大部分读写都在内存中完成。</li><li><strong>IO 多路复用</strong>：单线程监听处理所有网络连接。</li><li><strong>避免锁与上下文切换</strong>：单线程处理命令，保证了原子性，无并发锁开销。</li><li><strong>高效数据结构</strong>：如 SDS 简单动态字符串、跳跃表、压缩列表等。</li></ul></li><li><strong>Redis 6.0 多线程</strong>：仅在网络 IO 读写层面引入多线程以利用多核 CPU，<strong>命令的执行始终是单线程的</strong>，单个命令的原子性与延迟不受影响。</li></ul><hr><h3 id="_10-缓存与数据库双写一致性" tabindex="-1">10. 缓存与数据库双写一致性 <a class="header-anchor" href="#_10-缓存与数据库双写一致性" aria-label="Permalink to &quot;10. 缓存与数据库双写一致性&quot;">​</a></h3><ul><li><strong>策略与问题</strong>： <ul><li><strong>旁路缓存模式 (Cache-Aside)</strong>：<strong>先更新数据库，再删除缓存</strong>。若先删缓存，并发下可能读到旧数据并回写入缓存，产生脏数据。</li><li><strong>延时双删</strong>：先删缓存 → 更新数据库 → 延迟后再次删除缓存，以尽量删除并发写入的旧值。</li><li><strong>最终一致性方案</strong>：通过 Canal 等工具监听数据库 binlog，异步更新或删除缓存。</li></ul></li><li><strong>核心认知</strong>：追求绝对强一致性极难且代价巨大，业务通常选择<strong>最终一致性</strong>，并以缓存过期时间作为兜底。</li></ul><hr><h3 id="_11-事务、管道与-lua-脚本" tabindex="-1">11. 事务、管道与 Lua 脚本 <a class="header-anchor" href="#_11-事务、管道与-lua-脚本" aria-label="Permalink to &quot;11. 事务、管道与 Lua 脚本&quot;">​</a></h3><ul><li><p><strong>事务 (Transaction)</strong></p><ul><li>命令：<code>MULTI</code> → 命令入队 → <code>EXEC</code>（或 <code>DISCARD</code> 取消）。</li><li><strong>特性</strong>：执行时命令不会被其他客户端插队，但<strong>不支持回滚</strong>，某条命令失败不影响后续执行。</li><li><strong>乐观锁</strong>：通过 <code>WATCH key</code> 监控，在 <code>EXEC</code> 时若 key 被修改，则事务失败。</li></ul></li><li><p><strong>管道 (Pipeline)</strong></p><ul><li><strong>作用</strong>：客户端批量发送命令，减少网络往返时间（RTT）。</li><li><strong>与事务区别</strong>：纯客户端行为，不保证原子性和隔离性。</li><li><strong>注意</strong>：一次管道中命令不宜过多，需控制批量大小。</li></ul></li><li><p><strong>Lua 脚本</strong></p><ul><li><strong>用法</strong>：<code>EVAL</code> 将脚本提交至服务端执行。</li><li><strong>优点</strong>：保证脚本内操作的原子性；减少网络开销；可封装复杂逻辑。</li><li><strong>限制</strong>：不宜执行过久，会阻塞主线程；集群模式下需确保所有 Key 在同一分片（可用 <code>hash tags</code>）。</li></ul></li></ul><hr><h3 id="_12-内存淘汰策略详解" tabindex="-1">12. 内存淘汰策略详解 <a class="header-anchor" href="#_12-内存淘汰策略详解" aria-label="Permalink to &quot;12. 内存淘汰策略详解&quot;">​</a></h3><p>当内存达到 <code>maxmemory</code>，Redis 将按配置淘汰数据。</p><table tabindex="0"><thead><tr><th>策略</th><th>说明</th></tr></thead><tbody><tr><td><code>noeviction</code></td><td>不淘汰，拒绝新写入（默认）</td></tr><tr><td><code>allkeys-lru</code></td><td>在所有键中淘汰最近最少使用的</td></tr><tr><td><code>volatile-lru</code></td><td>在设了过期时间的键中淘汰 LRU</td></tr><tr><td><code>allkeys-lfu</code></td><td>在所有键中淘汰最近最不频繁使用的 (4.0+)</td></tr><tr><td><code>volatile-lfu</code></td><td>在设了过期时间的键中淘汰 LFU</td></tr><tr><td><code>allkeys-random</code></td><td>在所有键中随机淘汰</td></tr><tr><td><code>volatile-random</code></td><td>在设了过期时间的键中随机淘汰</td></tr><tr><td><code>volatile-ttl</code></td><td>淘汰存活时间（TTL）最短的键</td></tr></tbody></table><ul><li><strong>LRU vs LFU</strong>：LRU 关注“有多久没用”，LFU 关注“用的次数少”，后者更能区分冷热数据。</li><li><strong>注意</strong>：此策略独立于过期策略。过期键也可能因内存不足而被提前淘汰。</li></ul><hr><h3 id="_13-小对象编码优化" tabindex="-1">13. 小对象编码优化 <a class="header-anchor" href="#_13-小对象编码优化" aria-label="Permalink to &quot;13. 小对象编码优化&quot;">​</a></h3><p>Redis 内部会根据数据量自动选择内存优化的结构，减少内存占用。</p><ul><li><strong>Hash</strong>：当字段少、值短时使用 <code>ziplist</code>（紧凑连续数组），而非 <code>hashtable</code>。</li><li><strong>ZSet</strong>：元素少时用 <code>ziplist</code> 或 <code>listpack</code>（Redis 7.0+ 替代 ziplist）。</li><li><strong>Set</strong>：纯整数集合使用 <code>intset</code>。</li><li><strong>参数控制</strong>：<code>hash-max-ziplist-entries</code>、<code>hash-max-ziplist-value</code> 等，可设置阈值。超过阈值自动转为标准结构。</li><li><strong>优点</strong>：显著节约内存（约节省 30%~50%），操作时 CPU 略高但总体效率优。</li></ul><hr><h3 id="_14-热点-key-发现与解决" tabindex="-1">14. 热点 Key 发现与解决 <a class="header-anchor" href="#_14-热点-key-发现与解决" aria-label="Permalink to &quot;14. 热点 Key 发现与解决&quot;">​</a></h3><ul><li><strong>表现</strong>：某个 key 访问量极高，导致单分片 CPU/带宽打满，甚至拖垮 Redis 集群。</li><li><strong>发现</strong>：<code>redis-cli --hotkeys</code> 命令、客户端埋点监控、Proxy 层统计。</li><li><strong>解决方案</strong>： <ol><li><strong>本地缓存（二级缓存）</strong>：在应用进程内存中缓存热点数据，减轻 Redis 压力，配合短 TTL 或主动更新。</li><li><strong>热 key 复制（多副本）</strong>：将热点 key 复制多份到不同分片，key 名加随机后缀，请求时随机/轮询取。</li><li><strong>读写分离</strong>：热点 key 增加从节点，通过读从分摊压力。</li></ol></li></ul><hr><h3 id="_15-其他重要数据结构-bitmap、geo、stream" tabindex="-1">15. 其他重要数据结构（Bitmap、Geo、Stream） <a class="header-anchor" href="#_15-其他重要数据结构-bitmap、geo、stream" aria-label="Permalink to &quot;15. 其他重要数据结构（Bitmap、Geo、Stream）&quot;">​</a></h3><ul><li><p><strong>Bitmap</strong></p><ul><li>本质是 String，按位操作。适合存储布尔信息（签到、用户是否在线）。</li><li>命令：<code>SETBIT</code>、<code>GETBIT</code>、<code>BITCOUNT</code>、<code>BITOP</code>。</li><li>典型场景：<strong>用户签到统计</strong>（每日一亿用户只需约 12MB）。</li></ul></li><li><p><strong>Geo</strong></p><ul><li>基于 Sorted Set，存储地理位置信息（经纬度）。</li><li>命令：<code>GEOADD</code>、<code>GEODIST</code>、<code>GEORADIUS</code>、<code>GEOSEARCH</code>（6.2+）。</li><li>场景：<strong>附近的人、门店检索</strong>。</li></ul></li><li><p><strong>Stream</strong></p><ul><li>Redis 5.0 引入的持久化消息队列数据结构，支持消费者组、消息确认。</li><li>命令：<code>XADD</code>、<code>XREAD</code>、<code>XGROUP</code>、<code>XACK</code>。</li><li>场景：可靠的消息队列、事件溯源。</li></ul></li></ul><hr><h3 id="_16-慢查询日志" tabindex="-1">16. 慢查询日志 <a class="header-anchor" href="#_16-慢查询日志" aria-label="Permalink to &quot;16. 慢查询日志&quot;">​</a></h3><ul><li><strong>配置</strong>：<code>slowlog-log-slower-than 10000</code>（微秒，超过此值记录），<code>slowlog-max-len 128</code>。</li><li><strong>查看</strong>：<code>SLOWLOG GET [n]</code> 获取最近 n 条慢查询。</li><li><strong>分析</strong>：得到耗时长、复杂度高的命令（如 <code>KEYS *</code>、大集合的 <code>SORT</code> 等），进行优化或规避。</li><li><strong>注意</strong>：慢查询日志记录的是<strong>命令执行时间</strong>，不包含网络 I/O 和排队时间。</li></ul><hr><h3 id="_17-redis-与-memcached-对比" tabindex="-1">17. Redis 与 Memcached 对比 <a class="header-anchor" href="#_17-redis-与-memcached-对比" aria-label="Permalink to &quot;17. Redis 与 Memcached 对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比点</th><th>Redis</th><th>Memcached</th></tr></thead><tbody><tr><td>数据类型</td><td>丰富（String, Hash, List, Set, ZSet, Bitmap…）</td><td>仅简单 key-value</td></tr><tr><td>持久化</td><td>支持 RDB 和 AOF，可持久化到磁盘</td><td>不支持，纯内存缓存</td></tr><tr><td>集群</td><td>原生 Cluster 分片；哨兵高可用</td><td>需客户端分片（一致性哈希），无原生集群</td></tr><tr><td>线程模型</td><td>单线程执行命令（6.0 网络 IO 多线程）</td><td>多线程，扩展性好</td></tr><tr><td>内存管理</td><td>精细（jemalloc），有多种编码优化</td><td>固定大小 slab 分配，易浪费内存</td></tr><tr><td>功能丰富度</td><td>发布订阅、Lua 脚本、事务、过期策略、管道等</td><td>功能较单一</td></tr><tr><td>适用场景</td><td>需要丰富数据结构、持久化、高可用的各类场景</td><td>简单的缓存加速，对数据可靠性要求不高</td></tr></tbody></table><hr><h3 id="_18-底层数据结构原理" tabindex="-1">18. 底层数据结构原理 <a class="header-anchor" href="#_18-底层数据结构原理" aria-label="Permalink to &quot;18. 底层数据结构原理&quot;">​</a></h3><ul><li><strong>SDS (简单动态字符串)</strong><ul><li>Redis 的字符串实现，在 C 字符串基础上记录长度和已用空间，获取长度 O(1)，杜绝缓冲区溢出，并可惰性释放空间，减少内存重分配。</li></ul></li><li><strong>链表与 quicklist</strong><ul><li>早期 List 使用双向链表，内存开销大。Redis 3.2 后使用 <code>quicklist</code>，将链表节点与压缩列表结合，每个节点存放一个小型压缩列表，兼顾空间效率与操作性能。</li></ul></li><li><strong>字典 (dict)</strong><ul><li>Hash 类型的底层实现，使用两个哈希表实现渐进式 rehash，避免一次性 rehash 导致的卡顿。扩容时采用分而治之的方式逐步迁移键值对。</li></ul></li><li><strong>跳跃表 (skiplist)</strong><ul><li>ZSet 的底层实现之一，在有序链表基础上增加多级索引，查询效率与平衡树相当（O(log N)），但实现更简单，且适合范围查找。</li></ul></li><li><strong>整数集合 (intset)</strong><ul><li>Set 的底层实现之一，当元素全部为整数且数量较少时使用。内部是一个有序数组，可通过二分查找。插入新整数类型时会自动升级编码长度。</li></ul></li><li><strong>压缩列表 (ziplist) 与 listpack</strong><ul><li><code>ziplist</code> 是一块连续内存，用变长编码存储列表或哈希元素，十分节省内存，但存在连锁更新风险。Redis 7.0 起逐渐用 <code>listpack</code> 替代，结构更简单，避免了连锁更新，是未来主要的小对象编码方案。</li></ul></li></ul><hr><h3 id="_19-redis-6-0-7-0-重要新特性" tabindex="-1">19. Redis 6.0 / 7.0 重要新特性 <a class="header-anchor" href="#_19-redis-6-0-7-0-重要新特性" aria-label="Permalink to &quot;19. Redis 6.0 / 7.0 重要新特性&quot;">​</a></h3><ul><li><strong>IO 多线程</strong><br> 6.0 引入，将网络读写交由独立线程组处理，命令执行仍为单线程，显著提升高并发下的吞吐量。</li><li><strong>客户端缓存 (Server-assisted Client Side Caching)</strong><br> 利用 RESP3 推送机制，服务端通知客户端某些 key 已失效，减少网络查询。</li><li><strong>RESP3 协议</strong><br> 支持更丰富的数据类型，允许服务器主动推送信息，客户端库可更智能地处理连接。</li><li><strong>ACL 权限控制</strong><br> 支持多用户，可对用户按命令和 key 模式进行细粒度权限控制，提升安全性。</li><li><strong>Redis Functions (7.0)</strong><br> 作为 Lua 脚本的替代方案，由函数库管理，持久化存储在 RDB/AOF 中，支持版本控制和原子性部署，集群执行更可靠。</li><li><strong>listpack 全面替代 ziplist</strong><br> 7.0 将 <code>listpack</code> 作为哈希、有序集合等小对象的默认编码，从根本上解决连锁更新问题。</li></ul><hr><h3 id="_20-性能优化实战" tabindex="-1">20. 性能优化实战 <a class="header-anchor" href="#_20-性能优化实战" aria-label="Permalink to &quot;20. 性能优化实战&quot;">​</a></h3><ul><li><strong>绑定 CPU 核心</strong><br> 避免 Redis 进程在多个 CPU 核心间频繁切换，可提升单线程效率。建议绑定到同一个 NUMA 节点内的一个或多个核心。</li><li><strong>内存优化与碎片整理</strong><br> 配置 <code>activedefrag yes</code> 开启内存碎片自动整理；根据数据特点调整 <code>hash-max-ziplist-entries</code> 等参数，促进使用紧凑编码；定期 <code>MEMORY PURGE</code>。</li><li><strong>批量操作最佳实践</strong><ul><li>能用 <code>MGET</code> / <code>MSET</code> 的地方不用管道多次调用，原生命令更高效。</li><li>无法使用原生聚合命令（如需要不同 key 的类型）时再用 Pipeline 批量发送。</li><li>控制每批次处理量，避免大包占满带宽或导致 Redis 暂时阻塞。</li></ul></li><li><strong>避免 <code>KEYS</code> 命令</strong><br> 线上禁用，改用 <code>SCAN</code> 系列命令进行游标迭代，不会阻塞服务。</li><li><strong>合理设置 lazy free</strong><br> 配置 <code>lazyfree-lazy-eviction</code>、<code>lazyfree-lazy-expire</code> 等，让删除操作异步进行，减少主线程停顿。</li></ul><hr><h3 id="_21-实际场景设计案例" tabindex="-1">21. 实际场景设计案例 <a class="header-anchor" href="#_21-实际场景设计案例" aria-label="Permalink to &quot;21. 实际场景设计案例&quot;">​</a></h3><ul><li><strong>高并发抢红包系统</strong><ul><li><strong>红包金额拆分</strong>：利用 <code>LPUSH</code> + <code>LPOP</code> 将一个红包的所有金额拆分成多个金额存在 List 中，多线程用 <code>LPOP</code> 原子抢取。</li><li><strong>防超抢</strong>：<code>LPOP</code> 天然返回元素或 nil，不会超发。</li><li><strong>记录明细</strong>：抢到后异步记录到数据库，保证最终一致性。</li></ul></li><li><strong>可靠延迟队列</strong><ul><li><strong>ZSet 方案</strong>：score 存放任务执行时间戳，<code>ZRANGEBYSCORE</code> 捞取到期任务，结合 Lua 原子地移动至处理队列，并处理重试与死信。</li><li><strong>Stream 方案</strong>：通过消费者组 + <code>XREADGROUP</code> 从指定时间范围读取，利用消息确认和 <code>XPENDING</code> 实现重试，可靠性更高。</li></ul></li><li><strong>附近的人功能</strong><br> 使用 <code>GEOADD</code> 添加用户经纬度，<code>GEOSEARCH</code> 按半径搜索附近用户。可搭配 ZSet 的 score 更新用户最后上线时间，实现实时统计。</li><li><strong>实时排行榜</strong><ul><li>用 ZSet 存储积分，<code>ZADD</code> 实时更新，<code>ZREVRANK</code> 查排名，<code>ZREVRANGE</code> 取 Top N。</li><li>如需小时榜、日榜，可创建多个 ZSet，用 <code>ZUNIONSTORE</code> 合并，或到期切换。</li></ul></li><li><strong>千万级用户签到</strong><br> 以用户 ID 为 offset 的 Bitmap，每日占用约 12KB 空间（千万用户约 1.19MB），<code>SETBIT</code> 签到，<code>BITCOUNT</code> 统计日活，<code>BITOP</code> 可做连续签到分析。</li></ul>',70)])])}const b=o(i,[["render",d]]);export{u as __pageData,b as default};
